:root{--ink:#070a09;--panel:rgba(8,12,11,.93);--soft:rgba(9,15,14,.8);--paper:#e7e2d8;--cyan:#75d3d7;--amber:#d9a15c;--amber2:#f2bd73;--red:#df4a4a;--line:rgba(217,161,92,.48);--muted:#9b9b92;--font-ui:"Arial Narrow","Roboto Condensed",Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font-family:var(--font-ui)}button{font:inherit;cursor:pointer;color:inherit;background:transparent;border:1px solid var(--line);min-height:44px;transition:background .2s,border-color .2s,box-shadow .2s}button:hover{border-color:var(--cyan);background:#75d3d710}button:focus-visible,[role=button]:focus-visible{outline:2px solid var(--cyan);outline-offset:4px}button:disabled{opacity:.35;cursor:default}main{max-width:1680px;margin:auto;padding:30px 36px 16px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--line);min-height:84px}.brand{font-size:20px;font-weight:800;letter-spacing:4px}.brand em{font-style:normal;font-weight:400;color:var(--amber);margin-left:12px}.brand small{display:block;font-family:monospace;font-size:12px;color:var(--muted);letter-spacing:2px;margin-top:12px}nav{display:flex;align-self:stretch;gap:25px}.nav{border:0;text-transform:uppercase;letter-spacing:2px;font-size:14px;border-bottom:2px solid transparent;padding:12px}.nav.active{border-bottom-color:var(--cyan);color:var(--cyan)}.lab{font:900 12px var(--font-ui);letter-spacing:2px;color:var(--amber);border:1px solid #67573d;padding:9px}.heading{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:25px 0}h1{font-size:30px;font-weight:500;letter-spacing:.5px;margin:0 0 9px}p{line-height:1.6}.heading p{font-size:16px;color:var(--muted);margin:0}.origin{display:flex;align-items:center;gap:12px}.origin i{height:8px;width:8px;border-radius:50%;background:var(--cyan)}small,.kicker{font:900 12px var(--font-ui);letter-spacing:1.5px;color:var(--muted)}.origin strong{display:block;font-size:16px;font-weight:500;margin-top:7px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 365px;gap:22px;align-items:stretch}.mapbox{border:1px solid var(--line);position:relative;overflow:hidden;background:linear-gradient(#74927a0c 1px,transparent 1px),linear-gradient(90deg,#74927a0c 1px,transparent 1px),radial-gradient(ellipse at center,#17251e,#0b120f);background-size:40px 40px,40px 40px,auto;min-height:630px}.map-head{position:absolute;top:22px;left:22px;right:22px;display:flex;justify-content:space-between;font:900 12px var(--font-ui);letter-spacing:1.5px;z-index:2;pointer-events:none}.map-head span:last-child{color:var(--amber)}#viewport{height:100%;min-height:630px;touch-action:none;cursor:grab}#viewport.dragging{cursor:grabbing}#network{display:block;width:100%;height:100%;min-height:630px;user-select:none;overflow:hidden}#network text{pointer-events:none}.hit{cursor:pointer;outline:none}.hit .halo{fill:transparent;stroke:transparent;stroke-width:1.5;transition:fill .2s,stroke .2s}.hit:hover .halo,.hit:focus-visible .halo{fill:#75d3d71a;stroke:var(--cyan)}.hit.selected .halo{fill:#75d3d71a;stroke:var(--cyan);stroke-width:2}.hit .target{fill:transparent;stroke:none}.route-selected{fill:none;stroke:var(--cyan);stroke-width:4;stroke-linejoin:round;stroke-linecap:round;filter:drop-shadow(0 0 5px #75d3d780);pointer-events:none}.flow{fill:none;stroke:#dafdf4;stroke-width:2;stroke-dasharray:3 35;animation:flow 5s linear infinite;pointer-events:none}@keyframes flow{to{stroke-dashoffset:-152}}.map-footer{position:absolute;left:20px;right:20px;bottom:16px;display:flex;align-items:center;justify-content:space-between;gap:8px;pointer-events:none}.legend{display:flex;gap:15px;font-size:12px;color:var(--muted);flex-wrap:wrap}.legend span{display:flex;align-items:center;gap:7px}.legend i{width:17px;height:2px;background:var(--cyan)}.legend i.exposed{background:none;border-top:2px dashed var(--amber)}.legend .cut{color:#d89484}.controls{display:flex;gap:5px;pointer-events:auto}.controls button{width:44px;font-size:21px;background:#0b1511e8}#tooltip{position:absolute;z-index:5;width:254px;background:#11211bf5;border:1px solid #71c1bd;box-shadow:0 12px 30px #0009;padding:16px;pointer-events:none;animation:tooltip .2s ease-out}#tooltip strong{font-size:16px}#tooltip p{font-size:14px;color:var(--muted);margin:8px 0}#tooltip small{color:var(--cyan);letter-spacing:0;line-height:1.5;display:block}@keyframes tooltip{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}#detail{background:linear-gradient(145deg,#16231c,#0b130f);border:1px solid #455143;position:relative;min-width:0}#detail:before{content:'';position:absolute;top:-1px;left:-1px;width:78px;height:3px;background:var(--cyan)}.detail-scroll{height:100%;display:flex;flex-direction:column}.detail-scroll.changing{animation:sweep .38s ease-out}@keyframes sweep{from{opacity:0;transform:translateY(20px);clip-path:inset(100% 0 0)}to{opacity:1;transform:translateY(0);clip-path:inset(0)}}.detail-head,.detail-section,.detail-actions{padding:24px;border-bottom:1px solid var(--line)}h2{font-size:30px;font-weight:500;margin:16px 0 10px}.detail-head p{font-size:16px;color:#b8c2b6;margin-bottom:0}.kicker.cyan{color:var(--cyan)}.chips,.services{display:flex;gap:8px;flex-wrap:wrap}.chip{font-size:12px;color:#c9c4b6;border:1px solid #64735e;padding:4px 8px}.services span{border:1px solid #3c503d;background:#26392a55;color:#d3dccb;padding:7px 9px;font-size:14px;margin-top:12px}.steps{padding:0;margin:20px 0 0;list-style:none}.steps li{margin-left:5px;border-left:1px solid #4c8986;padding:0 0 21px 22px;position:relative;font-size:16px}.steps li:before{content:'';width:7px;height:7px;background:var(--cyan);border-radius:50%;position:absolute;left:-4px;top:4px}.steps li:last-child{border-color:transparent;padding-bottom:0}.steps small{display:block;font:14px var(--font-ui);letter-spacing:0;margin-top:6px;color:#a4b4a5;line-height:1.4}.notice{font-size:14px;line-height:1.5;border-left:2px solid var(--amber);padding-left:12px;margin-top:20px;color:#d2bd95}.detail-actions{border:0;margin-top:auto}.primary{width:100%;background:#18322f;border:1px solid #71c1bd;letter-spacing:1.5px;text-transform:uppercase;font-size:14px;padding:12px 16px;box-shadow:inset 0 0 18px #75d3d70b}.primary:hover{box-shadow:0 0 18px #75d3d720}.secondary{width:100%;margin-top:10px;font-size:14px;padding:10px}.alt{display:flex;gap:7px;margin-top:16px}.alt button{font-size:13px;padding:9px;flex:1}.alt button[aria-pressed=true]{color:var(--cyan);border-color:var(--cyan);background:#75d3d710}footer{display:flex;justify-content:space-between;gap:15px;border-top:1px solid var(--line);margin-top:22px;padding-top:17px;color:#8d9c90;font-size:12px}.mobile-open,.mobile-close{display:none}dialog{padding:0;border:1px solid #66806e;background:#0e1913;color:var(--paper);width:min(650px,calc(100% - 30px));max-height:calc(100dvh - 40px);overflow:auto;box-shadow:0 24px 80px #000b}dialog::backdrop{background:#020706c9;backdrop-filter:blur(4px)}dialog[open]{animation:panelUp .38s cubic-bezier(.2,.8,.2,1)}dialog.closing{animation:panelDown .28s ease-in forwards}dialog.closing::backdrop{animation:fade .28s reverse forwards}.dialog-shell{padding:32px}.close{position:absolute;top:12px;right:12px;width:44px;font-size:25px;z-index:2}.dialog-shell h2{padding-right:35px}.dialog-shell p{color:#b8c6b8;font-size:16px}.refuge-list{display:grid;gap:10px;margin-top:24px}.refuge-list button{padding:17px;text-align:left;background:#17231b}.refuge-list strong{display:block;font-size:17px}.refuge-list small{display:block;margin-top:7px;letter-spacing:0;font:14px var(--font-ui)}.journey{padding:18px 0}.journey li.active{color:var(--cyan)}.journey li.completed:before{background:#d9a15c}.journey-count{margin:20px 0 8px;color:var(--amber);font:900 13px var(--font-ui)}.sim-note{font-size:13px!important;border-top:1px solid var(--line);padding-top:18px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}#shade{display:none}@keyframes panelUp{from{opacity:0;transform:translateY(45px);clip-path:inset(100% 0 0)}to{opacity:1;transform:translateY(0);clip-path:inset(0)}}@keyframes panelDown{to{opacity:0;transform:translateY(50px);clip-path:inset(100% 0 0)}}@keyframes fade{from{opacity:0}to{opacity:1}}@media(min-width:1450px){.mapbox,#viewport,#network{min-height:704px}.layout{grid-template-columns:minmax(0,1fr) 406px}}@media(max-width:1050px){main{padding:20px}.layout{grid-template-columns:minmax(0,1fr) 320px;gap:14px}.detail-head,.detail-section,.detail-actions{padding:19px}.brand{font-size:17px;letter-spacing:2px}.lab{display:none}.origin{display:none}.mapbox,#viewport,#network{min-height:630px}.legend{gap:8px;font-size:11px}}@media(max-width:760px){main{padding:14px 12px 12px}header{min-height:95px;align-items:flex-start;gap:8px;flex-wrap:wrap}.brand{font-size:16px}.brand small{font-size:10px;letter-spacing:1px;margin-top:7px}nav{width:100%;gap:16px;height:43px}.nav{font-size:13px;padding:7px 4px;min-height:40px}.heading{padding:17px 0}h1{font-size:23px}.heading p{font-size:14px}.layout{display:block}.mapbox{height:calc(100dvh - 255px);min-height:400px}.mapbox #viewport,.mapbox #network{height:100%;min-height:0}.map-head{font-size:10px;left:14px;right:14px;top:14px;letter-spacing:1px}.map-footer{bottom:65px;left:12px;right:12px}.legend{gap:7px;max-width:185px;font-size:11px}.controls button{width:42px;min-height:42px}.mobile-open{display:block;position:absolute;bottom:0;left:0;width:100%;background:#15302a;border:0;border-top:1px solid #4c8986;color:var(--cyan);font-size:14px;min-height:52px}.mobile-close{display:block;position:absolute;top:10px;right:10px;width:44px;font-size:24px}.layout #detail{position:fixed;z-index:20;left:0;right:0;bottom:0;max-height:82dvh;overflow:auto;transform:translateY(105%);visibility:hidden;transition:transform .35s ease,visibility .35s;box-shadow:0 -20px 70px #000b}.layout #detail.open{transform:translateY(0);visibility:visible}.detail-head{padding-top:28px}.detail-head h2{font-size:27px}.detail-head p{font-size:16px}.detail-scroll{height:auto}.detail-section,.detail-head,.detail-actions{padding:22px}.detail-actions{padding-bottom:calc(22px + env(safe-area-inset-bottom))}#shade.open{display:block;position:fixed;inset:0;background:#010504ae;z-index:19;animation:fade .3s}footer{font-size:11px;margin-top:13px;line-height:1.4;flex-direction:column;gap:4px}dialog{max-height:88dvh}.dialog-shell{padding:26px 22px}#tooltip{display:none!important}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}

/* UI tokens and control hierarchy from Neosantiago-rpg-demo/neosantiago-demo.html.
   Keep the exact system-font fallback chain used by the game; no remote fonts. */
.brand{color:var(--amber2);font-weight:900;letter-spacing:.16em}
.brand em{color:var(--amber2)}
h1,h2{font-family:var(--font-ui);font-weight:900;line-height:1.08;letter-spacing:.055em;text-transform:uppercase}
h1{color:var(--paper)}h2{color:var(--amber2)}
.kicker,.map-head,.brand small,.origin small,.lab{font-family:var(--font-ui);font-weight:900;letter-spacing:.16em;text-transform:uppercase}
#network text{font-family:var(--font-ui)}
#network .label{font-weight:900;letter-spacing:.055em}
#network .sub,#network .tiny{font-family:var(--font-ui);font-weight:800}
button{font-family:var(--font-ui);font-weight:900;letter-spacing:.1em;text-transform:uppercase;border-radius:0}
button:hover:not(:disabled){border-color:var(--amber2);background:rgba(217,161,92,.1)}
button:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}
.primary,.secondary{min-height:49px;padding:11px 19px;border:1px solid var(--amber);font-weight:900;letter-spacing:.12em;text-transform:uppercase;box-shadow:none}
.primary{color:var(--ink);background:var(--amber)}
.primary:hover:not(:disabled){color:var(--ink);background:var(--amber2);border-color:var(--amber2);box-shadow:0 0 18px rgba(217,161,92,.12)}
.secondary{color:var(--paper);background:transparent}
.secondary:hover:not(:disabled){color:var(--amber2);background:rgba(217,161,92,.1)}
.controls button,.close,.mobile-close{color:var(--amber2);border:1px solid var(--line);background:rgba(217,161,92,.04)}
.controls button{letter-spacing:0}
.nav{color:var(--muted);font-weight:900;letter-spacing:.16em}
.nav:hover:not(:disabled){color:var(--amber2);background:rgba(217,161,92,.05)}
.nav.active{color:var(--cyan);border-bottom-color:var(--cyan)}
.refuge-list button{border-color:rgba(217,161,92,.56);background:rgba(255,255,255,.015);transition:transform .16s,background .16s,border-color .16s}
.refuge-list button:hover{transform:translateX(3px);border-color:var(--amber2);background:rgba(217,161,92,.1)}
.refuge-list strong{font-weight:900;letter-spacing:.075em}
.refuge-list small{font-family:var(--font-ui);font-weight:400;text-transform:none;letter-spacing:0}
.alt button{border-color:var(--line);color:var(--paper);background:transparent}
.alt button[aria-pressed=true]{color:var(--amber2);border-color:var(--amber2);background:rgba(217,161,92,.08);box-shadow:inset 0 -2px rgba(217,161,92,.42)}
#detail,dialog{border-color:var(--line);background:linear-gradient(145deg,#0a0f0e,#080b0a)}
.detail-head,.detail-section{border-color:rgba(217,161,92,.25)}
.services span{border-color:rgba(217,161,92,.25);background:rgba(217,161,92,.035);color:var(--paper)}
.chip{border-color:rgba(217,161,92,.4);color:var(--amber2);font-family:var(--font-ui);font-weight:800}
#tooltip{border-color:var(--line);background:rgba(6,10,9,.98)}
#tooltip strong{color:var(--amber2);font-weight:900;letter-spacing:.075em;text-transform:uppercase}
.detail-head p,.dialog-shell p{color:#dcd8cf}
@media(max-width:760px){.brand{letter-spacing:.1em}.mobile-open{color:var(--amber2);border-top-color:var(--line);background:rgba(8,12,11,.98);font-size:14px}.nav{letter-spacing:.1em}.mobile-close{min-height:44px}.detail-head h2{padding-right:34px}.alt button{font-size:13px;letter-spacing:.04em}.map-head{letter-spacing:.08em}}

'use strict';
const $=s=>document.querySelector(s),NS='http://www.w3.org/2000/svg';
const heroesToFranklin='M340 325V392Q340 403 348 411L380 443', franklinToLeones='M380 443H767Q780 443 780 430V247Q780 234 771 225L750 204',heroesToCisterna='M340 325V392Q340 403 348 411L380 443L432 495Q440 503 440 514V625',cisternaToVicuna='M440 625H824Q839 625 849 615L945 519',toTobalaba='M750 204L794 160',toVicuna='M794 160L975 341Q985 351 985 366V467Q985 479 977 487L945 519';
const data={
 heroes:{name:'Los Héroes',x:340,y:325,lines:['L1','L2'],kind:'Cazadores y exploradores',desc:'Punto de partida de las expediciones. Aquí se reúnen quienes conocen el terreno y quienes salen a conseguir alimento y recursos.',services:['Exploración','Caza'],paths:[],steps:[['Los Héroes','Punto de partida del laboratorio']],note:'República está al poniente. Hacia el oriente, el paso de Línea 1 queda cortado en Baquedano.'},
 republica:{name:'República',x:175,y:325,lines:['L1'],kind:'Puesto médico',desc:'Un pequeño puesto de medicinas junto a Los Héroes. Su cercanía lo convierte en el primer apoyo sanitario de esta red.',services:['Medicinas','Apoyo sanitario'],paths:['M340 325H175'],steps:[['Los Héroes','Línea 1 hacia el poniente'],['República','Llegada al puesto médico']],note:'La línea queda cortada después de República.'},
 plaza:{name:'Plaza de Armas',x:440,y:265,lines:['L3','L5'],kind:'Comunidad por definir',desc:'Comunidad propuesta de cultivo subterráneo y medicina ancestral. Su identidad definitiva todavía está en desarrollo.',services:['Cultivos · propuesta','Medicina ancestral · propuesta'],paths:['M340 325H440V265'],steps:[['Los Héroes','Línea 1 hacia Universidad de Chile'],['Universidad de Chile','Antiguo acceso de combinación a Línea 3'],['Plaza de Armas','Comunidad intermedia del corredor norte']],note:'Las combinaciones alternativas aún deben definirse. Esta prueba muestra el recorrido que acordamos.'},
 libertadores:{name:'Los Libertadores',x:220,y:95,lines:['L3'],kind:'Alimentos e hidroponía',desc:'Los mayores huertos hidropónicos de la ciudad sostienen a otras comunidades. Sus sistemas de riego necesitan energía, combustible orgánico y mantenimiento.',services:['Producción de alimentos','Huertos hidropónicos'],paths:['M340 325H440V186Q440 171 426 166L220 95'],steps:[['Los Héroes','Línea 1 hacia Universidad de Chile'],['Universidad de Chile','Combinación a Línea 3'],['Plaza de Armas','Paso por la comunidad intermedia'],['Los Libertadores','Continuar por los túneles hacia el norte']],note:'Un viaje de gran exigencia logística. Las estaciones intermedias pueden tener salidas a superficie; sus eventos todavía no están definidos.'},
 leones:{name:'Los Leones',x:750,y:204,lines:['L1','L6'],kind:'Refugio de talleres',desc:'Suministros eléctricos y talleres del subsuelo. Una conexión esencial para mantener funcionando los refugios.',services:['Suministros eléctricos','Talleres'],paths:[heroesToFranklin,franklinToLeones],steps:[['Los Héroes','Tomar el corredor de Línea 2'],['Franklin','Combinación hacia Línea 6'],['Los Leones','Llegada al refugio de talleres']],note:'La Línea 1 está cortada en Baquedano. El acceso continúa por Franklin.'},
 vicuna:{name:'Vicuña Mackenna',x:945,y:519,lines:['L4','L4A'],kind:'El Frente',desc:'El refugio fortificado de El Frente. Recupera y distribuye armas y municiones; la seguridad de su interior contrasta con el peligro de sus accesos.',services:['Armas y municiones','Defensa de los refugios'],paths:[heroesToCisterna,cisternaToVicuna],steps:[['Los Héroes','Línea 2 hacia el sur'],['La Cisterna','Combinación hacia Línea 4A'],['Vicuña Mackenna','Tramo abierto y llegada al refugio']],note:'L4A atraviesa una trinchera abierta. El otro acceso pasa por Los Leones y la superficie vigilada de El Valle.'}
};
let selected='leones',alternative=false,journeyStep=0,dialogClosing=false,lastFocus=null,view={x:0,y:0,w:1090,h:704},pointerState=null,pointers=new Map(),pinch=null;
function current(){const d=data[selected];if(selected==='vicuna'&&alternative)return {...d,paths:[heroesToFranklin,franklinToLeones,toTobalaba,toVicuna],steps:[['Los Héroes','Línea 2 hacia Franklin'],['Franklin','Combinación hacia Línea 6'],['Los Leones','Salida a superficie'],['Tobalaba','Escotilla en zona de vigilancia de El Valle'],['Vicuña Mackenna','Continuar por Línea 4']],note:'La superficie junto al ex Costanera está fuertemente vigilada. Es el acceso de mayor exposición a la seguridad de El Valle.'};return d;}
function drawRoute(d){$('#routeGlow').replaceChildren();for(const path of d.paths){for(const cls of ['route-selected','flow']){const el=document.createElementNS(NS,'path');el.setAttribute('d',path);el.setAttribute('class',cls);$('#routeGlow').append(el);}}document.querySelectorAll('.hit').forEach(n=>{const on=n.dataset.key===selected;n.classList.toggle('selected',on);n.setAttribute('aria-pressed',String(on));});}
function stepsHTML(d){return '<ol class="steps">'+d.steps.map(([name,desc])=>`<li>${name}<small>${desc}</small></li>`).join('')+'</ol>';}
function renderDetail(){const d=current();drawRoute(d);const content=$('#detailContent');content.innerHTML=`<div class="detail-head"><button class="mobile-close" id="closeDetail" aria-label="Cerrar ficha">×</button><div class="kicker cyan">DESTINO SELECCIONADO</div><h2>${d.name}</h2><div class="chips">${d.lines.map(l=>`<span class="chip">${l}</span>`).join('')}<span class="chip">${d.kind}</span></div><p>${d.desc}</p></div><div class="detail-section"><div class="kicker">ACTIVIDAD DEL REFUGIO</div><div class="services">${d.services.map(s=>`<span>${s}</span>`).join('')}</div></div><div class="detail-section"><div class="kicker">RECORRIDO DESDE LOS HÉROES</div>${selected==='vicuna'?`<div class="alt" aria-label="Elegir acceso"><button id="southRoute" aria-pressed="${!alternative}">Por La Cisterna</button><button id="eastRoute" aria-pressed="${alternative}">Por Tobalaba</button></div>`:''}${stepsHTML(d)}<div class="notice">${d.note}</div></div><div class="detail-actions"><button class="primary" id="reviewRoute">${selected==='heroes'?'Elegir destino':'Revisar recorrido →'}</button><button class="secondary" id="centerDestination">Centrar destino</button></div>`;content.classList.remove('changing');void content.offsetWidth;content.classList.add('changing');$('#closeDetail').onclick=closeDetail;$('#reviewRoute').onclick=()=>selected==='heroes'?showRefuges():showRoute();$('#centerDestination').onclick=()=>{focusStation(d);closeDetail();};if(selected==='vicuna'){$('#southRoute').onclick=()=>chooseAlternative(false);$('#eastRoute').onclick=()=>chooseAlternative(true);}$('#openDetail').textContent=d.name+' · ver ficha ↑';$('#announcement').textContent='Destino seleccionado: '+d.name;}
function chooseAlternative(value){alternative=value;renderDetail();}
function selectStation(key,open=true){if(!Object.hasOwn(data,key))throw Error('Refugio desconocido');selected=key;alternative=false;renderDetail();hideTip();if(open&&matchMedia('(max-width:760px)').matches)openDetail();}
function openDetail(){$('#detail').classList.add('open');$('#shade').classList.add('open');$('#closeDetail').focus({preventScroll:true});}
function closeDetail(){$('#detail').classList.remove('open');$('#shade').classList.remove('open');}
$('#openDetail').onclick=openDetail;$('#shade').onclick=closeDetail;
function showTip(key,ev){if(matchMedia('(max-width:760px)').matches)return;const d=data[key],tip=$('#tooltip');tip.innerHTML=`<strong>${d.name}</strong><p>${d.kind}</p><small>${d.steps.map(s=>s[0]).join(' → ')}</small><p>Toca para abrir su ficha.</p>`;tip.hidden=false;const box=$('.mapbox').getBoundingClientRect();const el=ev.currentTarget.getBoundingClientRect();const x=ev.clientX||el.left+el.width/2,y=ev.clientY||el.top;tip.style.left=Math.max(10,Math.min(box.width-274,x-box.left+15))+'px';tip.style.top=Math.max(46,Math.min(box.height-tip.offsetHeight-76,y-box.top-20))+'px';}
function hideTip(){$('#tooltip').hidden=true;}
