function applyView(){view.w=Math.max(300,Math.min(1090,view.w));view.h=view.w*704/1090;view.x=Math.max(0,Math.min(1090-view.w,view.x));view.y=Math.max(0,Math.min(704-view.h,view.y));$('#network').setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);$('#zoomOut').disabled=view.w>=1090;$('#zoomIn').disabled=view.w<=300;hideTip();}
function zoom(factor,cx=view.x+view.w/2,cy=view.y+view.h/2){const w=view.w,h=view.h;view.w=Math.max(300,Math.min(1090,w*factor));view.h=view.w*704/1090;view.x=cx-(cx-view.x)*view.w/w;view.y=cy-(cy-view.y)*view.h/h;applyView();}
function resetView(){view={x:0,y:0,w:1090,h:704};applyView();}
function focusStation(d){view={x:d.x-260,y:d.y-168,w:520,h:520*704/1090};applyView();}
