function endPointer(e){pointers.delete(e.pointerId);pinch=null;vp.classList.remove('dragging');setTimeout(()=>{if(!pointers.size)pointerState=null;},50);}vp.addEventListener('pointerup',endPointer);vp.addEventListener('pointercancel',endPointer);vp.addEventListener('pointerleave',e=>{if(!vp.hasPointerCapture(e.pointerId))endPointer(e);});
